package org.securemail.identity;

import org.securemail.ecosystem.protocol.IdentityProtocol;
import java.io.*;
import java.net.InetSocketAddress;
import java.nio.file.*;
import java.security.*;
import java.security.spec.PKCS8EncodedKeySpec;
import java.time.Clock;
import java.util.*;
import java.util.concurrent.CountDownLatch;

/** Server operator CLI. Never reads an account private key or a release signing key. */
public final class IdentityMain {
    private IdentityMain() { }
    public static void main(String[] args)throws Exception {
        List<String> words=new ArrayList<>();Map<String,String> options=new LinkedHashMap<>();for(int i=0;i<args.length;i++){if(args[i].startsWith("--")){if(i+1>=args.length||args[i+1].startsWith("--")||options.put(args[i],args[++i])!=null)throw new IllegalArgumentException("Некорректные параметры");}else words.add(args[i]);}
        if(!Set.of("--home","--port","--account-id","--challenge","--proof","--public","--fingerprint","--request").containsAll(options.keySet()))throw new IllegalArgumentException("Неизвестный параметр");
        Path home=Path.of(options.getOrDefault("--home","/var/lib/aegis-identity")).toAbsolutePath().normalize();if(Files.isSymbolicLink(home))throw new IOException("Символический каталог Identity запрещён");
        if(words.equals(List.of("init"))){if(Files.exists(home.resolve("service.key"))||Files.exists(home.resolve("audit.key")))throw new IOException("Identity уже подготовлен");Files.createDirectories(home);privateMode(home,true);KeyPair key=KeyPairGenerator.getInstance("Ed25519").generateKeyPair();byte[] audit=new byte[32];new SecureRandom().nextBytes(audit);writePrivate(home.resolve("service.key"),encodeKey(key));writePrivate(home.resolve("audit.key"),audit);Files.writeString(home.resolve("service-public.txt"),IdentityProtocol.b64(key.getPublic().getEncoded())+"\n",StandardOpenOption.CREATE_NEW);try(IdentityStore initialized=new IdentityStore(home.resolve("identity.db"),key,audit,Clock.systemUTC())){System.out.println("Identity подготовлен. Отпечаток сервиса: "+initialized.audience());}finally{Arrays.fill(audit,(byte)0);}return;}
        KeyPair key=decodeKey(readPrivate(home.resolve("service.key"),256));byte[] audit=readPrivate(home.resolve("audit.key"),32);try(IdentityStore store=new IdentityStore(home.resolve("identity.db"),key,audit,Clock.systemUTC())){
            if(words.equals(List.of("serve"))){int port=Integer.parseInt(options.getOrDefault("--port","19120"));if(port<1||port>65535)throw new IllegalArgumentException("Порт");try(IdentityHttpServer http=new IdentityHttpServer(new InetSocketAddress("127.0.0.1",port),store,key)){http.start();System.out.println("Identity слушает loopback:"+http.port()+". Требуется отдельный Tor onion service.");CountDownLatch stopped=new CountDownLatch(1);Thread hook=new Thread(stopped::countDown,"identity-shutdown");Runtime.getRuntime().addShutdownHook(hook);try{stopped.await();}finally{Runtime.getRuntime().removeShutdownHook(hook);}}}
            else if(words.equals(List.of("inspect")))System.out.println( new String(IdentityJson.bytes(Map.of("audience",store.audience(),"auditIntegrity",store.verifyAudit(),"productionDeployed",false)),java.nio.charset.StandardCharsets.UTF_8));
            else if(words.equals(List.of("service","relay","allow"))){byte[] publicKey=IdentityProtocol.unb64(new String(readPublic(Path.of(required(options,"--public")),256),java.nio.charset.StandardCharsets.US_ASCII).trim(),44);store.allowRelayService(publicKey,required(options,"--fingerprint"));System.out.println("Публичный ключ Relay разрешён только для защищённого запроса managedAccount.");}
            else if(words.equals(List.of("service","relay","revoke"))){store.revokeRelayService(required(options,"--fingerprint"));System.out.println("Разрешение ключа Relay отозвано.");}
            else if(words.equals(List.of("owner","transfer"))||words.equals(List.of("owner","first-delegate"))){
                boolean transfer=words.get(1).equals("transfer"),create=options.containsKey("--challenge");
                if(create==options.containsKey("--proof")||create!=options.containsKey("--request"))throw new IllegalArgumentException("Нужны --request FILE --challenge FILE либо --proof FILE");
                Map<String,Object> d=IdentityJson.parse(readPublic(Path.of(required(options,create?"--request":"--proof")),16384));
                if(create){IdentityJson.keys(d,transfer?new String[]{"capability","targetAccountId","time","nonce","proof"}:new String[]{"capability","targetAccountId","roleName","time","nonce","proof"});var cap=IdentityProtocol.decodeCapability(IdentityJson.text(d,"capability",4096));Map<String,Object> c=transfer?store.ownerTransferChallenge(cap,IdentityJson.text(d,"targetAccountId",64),IdentityJson.number(d,"time"),IdentityJson.text(d,"nonce",43),IdentityJson.binary(d,"proof",64)):store.firstDelegateChallenge(cap,IdentityJson.text(d,"targetAccountId",64),IdentityJson.text(d,"roleName",80),IdentityJson.number(d,"time"),IdentityJson.text(d,"nonce",43),IdentityJson.binary(d,"proof",64));writePublic(Path.of(required(options,"--challenge")),IdentityJson.bytes(c));System.out.println("Публичное одноразовое задание создано. Корневые подтверждения выполняются только фиксированным согласием Почты.");}
                else if(transfer){IdentityJson.keys(d,"capability","challenge","requestId","ownerRootProof","ownerDeviceProof","targetRootProof","targetDeviceProof","time","nonce","proof");store.completeOwnerTransfer(IdentityProtocol.decodeCapability(IdentityJson.text(d,"capability",4096)),IdentityJson.text(d,"challenge",43),IdentityJson.text(d,"requestId",43),IdentityJson.binary(d,"ownerRootProof",64),IdentityJson.binary(d,"ownerDeviceProof",64),IdentityJson.binary(d,"targetRootProof",64),IdentityJson.binary(d,"targetDeviceProof",64),IdentityJson.number(d,"time"),IdentityJson.text(d,"nonce",43),IdentityJson.binary(d,"proof",64));System.out.println("Владелец изменён. Обе сессии отозваны; требуется новый вход.");}
                else{IdentityJson.keys(d,"challenge","ownerRootProof","ownerDeviceProof","targetRootProof","targetDeviceProof");store.completeFirstDelegation(IdentityJson.text(d,"challenge",43),IdentityJson.binary(d,"ownerRootProof",64),IdentityJson.binary(d,"ownerDeviceProof",64),IdentityJson.binary(d,"targetRootProof",64),IdentityJson.binary(d,"targetDeviceProof",64));System.out.println("Первый независимый администратор назначен. Повтор начальной процедуры запрещён.");}
            }
            else if(words.equals(List.of("owner","bootstrap"))){String account=IdentityProtocol.idValue(required(options,"--account-id"));boolean challenge=options.containsKey("--challenge"),proof=options.containsKey("--proof");if(challenge==proof)throw new IllegalArgumentException("Укажите --challenge FILE либо --proof FILE");if(challenge){IdentityStore.OwnerChallenge c=store.ownerChallenge(account);byte[] bytes=IdentityProtocol.ownerBootstrap(store.audience(),account,c.challenge(),c.expiresAt());Map<String,Object> document=Map.of("type","AEGIS-OWNER-BOOTSTRAP/v1","audience",store.audience(),"accountId",account,"challenge",c.challenge(),"expiresAt",c.expiresAt(),"proofBytes",IdentityProtocol.b64(bytes),"bootstrap",IdentityProtocol.b64(bytes));writePublic(Path.of(options.get("--challenge")),IdentityJson.bytes(document));System.out.println("Одноразовое публичное задание записано. Подпишите точные proofBytes через Почту после повторной аутентификации; приватный ключ не передавайте серверу.");}else{Map<String,Object> document=IdentityJson.parse(readPublic(Path.of(options.get("--proof")),4096));IdentityJson.keys(document,"audience","accountId","challenge","signature");if(!store.audience().equals(IdentityJson.text(document,"audience",64))||!account.equals(IdentityJson.text(document,"accountId",64)))throw new IdentityException("DENIED");store.bootstrapOwner(account,IdentityJson.text(document,"challenge",43),IdentityJson.binary(document,"signature",64));System.out.println("Владелец АЕГИС назначен. Повторный Owner Bootstrap запрещён.");}}
            else throw new IllegalArgumentException("Команды: init | serve | inspect | owner transfer/first-delegate --request FILE --challenge FILE / --proof FILE | owner bootstrap --account-id ID --challenge FILE / --proof FILE | service relay allow --public FILE --fingerprint SHA256 | service relay revoke --fingerprint SHA256; --home DIR");
        }finally{Arrays.fill(audit,(byte)0);}
    }
    private static String required(Map<String,String> options,String key){String value=options.get(key);if(value==null)throw new IllegalArgumentException("Отсутствует "+key);return value;}
    private static byte[] encodeKey(KeyPair pair)throws IOException {ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(DataOutputStream out=new DataOutputStream(bytes)){out.writeUTF("AEGIS-IDENTITY-SERVICE/v1");out.writeInt(pair.getPublic().getEncoded().length);out.write(pair.getPublic().getEncoded());out.writeInt(pair.getPrivate().getEncoded().length);out.write(pair.getPrivate().getEncoded());}return bytes.toByteArray();}
    private static KeyPair decodeKey(byte[] bytes)throws Exception {try(DataInputStream in=new DataInputStream(new ByteArrayInputStream(bytes))){if(!in.readUTF().equals("AEGIS-IDENTITY-SERVICE/v1"))throw new IOException("Формат ключа сервиса");int n=in.readInt();if(n!=44)throw new IOException("Размер ключа");byte[] pub=in.readNBytes(n);int m=in.readInt();if(m<32||m>128)throw new IOException("Размер ключа");byte[] secret=in.readNBytes(m);if(secret.length!=m||in.read()!=-1)throw new IOException("Формат ключа");try{return new KeyPair(IdentityProtocol.publicKey(pub),KeyFactory.getInstance("Ed25519").generatePrivate(new PKCS8EncodedKeySpec(secret)));}finally{Arrays.fill(secret,(byte)0);}}finally{Arrays.fill(bytes,(byte)0);}}
    private static byte[] readPrivate(Path file,int max)throws IOException {if(Files.isSymbolicLink(file)||!Files.isRegularFile(file,LinkOption.NOFOLLOW_LINKS)||Files.size(file)>max)throw new IOException("Защищённый файл сервиса недоступен");try{Set<java.nio.file.attribute.PosixFilePermission> p=Files.getPosixFilePermissions(file);if(!p.equals(PosixFilePermissions600.file()))throw new IOException("Требуются права 0600");}catch(UnsupportedOperationException ignored){}return Files.readAllBytes(file);}
    private static byte[] readPublic(Path file,int max)throws IOException {if(Files.isSymbolicLink(file)||!Files.isRegularFile(file,LinkOption.NOFOLLOW_LINKS)||Files.size(file)>max)throw new IOException("Файл доказательства недоступен");return Files.readAllBytes(file);}
    private static void writePrivate(Path file,byte[] bytes)throws IOException {try{Files.createFile(file,java.nio.file.attribute.PosixFilePermissions.asFileAttribute(PosixFilePermissions600.file()));}catch(UnsupportedOperationException e){Files.createFile(file);}try{Files.write(file,bytes,StandardOpenOption.WRITE);privateMode(file,false);}finally{Arrays.fill(bytes,(byte)0);}}
    private static void writePublic(Path file,byte[] bytes)throws IOException {if(file.toAbsolutePath().getParent()!=null)Files.createDirectories(file.toAbsolutePath().getParent());Files.write(file,bytes,StandardOpenOption.CREATE_NEW);}
    private static void privateMode(Path file,boolean directory)throws IOException {try{Files.setPosixFilePermissions(file,directory?PosixFilePermissions600.directory():PosixFilePermissions600.file());}catch(UnsupportedOperationException ignored) { }}
}
